  -- the planner's bank request in one number (parameter util_tp_bank_plan): squad set, team type, slot
  function TP.PlanCode(set, ty, slot)
    return set * 256 + (ty or 0) * 32 + slot
  end

  function TP.PlanDecode(code)
    if type(code) ~= "number" or code < 0 then
      return nil
    end
    return math.floor(code / 256), math.floor((code % 256) / 32), code % 32
  end

  function TP.Log(...)
    pcall(funcLuaCommand, TP.C.LOG, "BetterQoL team_planner", ...)
  end

  function TP.M(cmd, ...)        -- a menu command, errors swallowed
    local ok, a, b = pcall(funcLuaMenuCommand, cmd, ...)
    if ok then
      return a, b
    end
    return nil
  end

  function TP.Cmd(cmd, ...)      -- a script command of BetterQoL (nil when not answered)
    local ok, a, b, c, d, e, f, g, h, i, j = pcall(funcLuaCommand, cmd, ...)
    if ok then
      return a, b, c, d, e, f, g, h, i, j
    end
    return nil
  end

  function TP.Snd(id)
    pcall(funcLuaCommand, TP.C.SND, id)
  end

  function TP.Text(id, fallback)
    local ok, s = pcall(funcLuaCommand, TP.C.TEXT_GET, id)
    if ok and type(s) == "string" and s ~= "" then
      return s
    end
    return fallback
  end

  function TP.Msg(id, fallback, ...)
    local s = TP.Text(id, fallback)
    if select("#", ...) > 0 then
      local ok, f = pcall(string.format, s, ...)
      s = ok and f or s
    end
    pcall(funcLuaCommand, TP.C.SYS_MSG, s, 0, 0, 0, 0, 0, false)
  end

  -- on, ghost alpha, display rarity (the planner works in this save slot)
  function TP.Info()
    local on, alpha, rarity = TP.Cmd(TP.C.INFO)
    if on ~= true then
      return false, 1, 4
    end
    return true, type(alpha) == "number" and alpha or 0.45, type(rarity) == "number" and rarity or 4
  end

  -- slot -> param of a squad, and the display rarity
  function TP.Plans(set, ty)
    local out = {}
    local s, rarity = TP.Cmd(TP.C.LIST, set, ty or 0)
    if type(s) == "string" then
      for slot, param in s:gmatch("(%d+):(%d+)") do
        out[tonumber(slot)] = tonumber(param)
      end
    end
    return out, type(rarity) == "number" and rarity or 4
  end

  function TP.SetPlan(set, ty, slot, param)
    return TP.Cmd(TP.C.SET, set, ty or 0, slot, param or 0) == true
  end

  -- the character in a squad slot (0 = empty); the coach is slot 19
  function TP.Occupant(set, ty, slot)
    if type(SearchTeamSetCharaStHdlByScPosNo) ~= "function" then
      return 0
    end
    local ok, h = pcall(SearchTeamSetCharaStHdlByScPosNo, slot, set, ty or 0)
    if ok and type(h) == "number" and h ~= 0 then
      if type(IsInvalidSoccerCharaHdl) == "function" and IsInvalidSoccerCharaHdl(h) then
        return 0
      end
      return h
    end
    return 0
  end

  -- the slots of a squad that hold a ghost (planned and still empty); plans of slots filled by hand are dropped
  function TP.GhostSlots(set, ty)
    local out, n = {}, 0
    local plans = TP.Plans(set, ty)
    for slot, param in pairs(plans) do
      if TP.Occupant(set, ty, slot) ~= 0 then
        if not TP.keep_plans then   -- a real card taking a plan's slot: its plan moves when the swap has ended
          TP.SetPlan(set, ty, slot, 0)
          TP.Log("squad", set, ty, "slot", slot, "filled by hand: plan dropped")
        end
      else
        out[slot] = param
        n = n + 1
      end
    end
    return out, n
  end

  function TP.HasGhosts(set, ty)
    if type(set) ~= "number" or not TP.Info() then
      return false
    end
    local _, n = TP.GhostSlots(set, ty or 0)
    return n > 0
  end

  -- an owned character into a squad slot with the game's own check and bank placement; true when he is there
  function TP.Place(set, ty, slot, h)
    local okC, accept, code = pcall(funcLuaCommand, TP.C.PLACE_CHECK, h, set, slot, TP.FROM_BANK, ty)
    if not (okC and accept) then
      TP.Log("squad", set, ty, "slot", slot, "copy", h, "refused by the game's check, code", tostring(code))
      return false
    end
    TP.M(TP.C.PLACE_PREP, h)
    local okP = pcall(funcLuaCommand, TP.C.PLACE, set, slot, TP.FROM_BANK, h, ty)
    if okP and TP.Occupant(set, ty, slot) == h then
      return true
    end
    TP.Log("squad", set, ty, "slot", slot, "placement of", h, "did not stick")
    return false
  end

  -- a ghost's real copy: the first qualifying owned copy that is not in the squad yet and that the game's own check
  -- accepts for the slot, placed with the game's own placement; returns the handle or nil
  function TP.AssignSlot(set, ty, slot, param)
    local list = TP.Cmd(TP.C.CANDIDATES, param)
    if type(list) ~= "string" or list == "" then
      return nil
    end
    for hs in list:gmatch("%d+") do
      local h = tonumber(hs)
      local used = false
      if type(IsCharaInTeam) == "function" then
        local okU, u = pcall(IsCharaInTeam, h, set)
        used = okU and u == true
      end
      if not used then
        if TP.Place(set, ty, slot, h) then
          TP.Cmd(TP.C.ASSIGNED, set, ty, slot, h)
          return h
        end
      end
    end
    return nil
  end

  -- every ghost of the mounted page whose character the save now has; returns how many were placed
  function TP.AssignAll()
    if not TP.Info() then
      return 0
    end
    local squads = TP.Cmd(TP.C.PENDING)
    if type(squads) ~= "string" or squads == "" then
      return 0
    end
    local n = 0
    for s, t in squads:gmatch("(%d+):(%d+)") do
      local set, ty = tonumber(s), tonumber(t)
      local ghosts = TP.GhostSlots(set, ty)
      for slot, param in pairs(ghosts) do
        if TP.AssignSlot(set, ty, slot, param) then
          n = n + 1
        end
      end
    end
    if n > 0 then
      TP.Log("assigned", n, "planned player(s)")
    end
    return n
  end

  -- ---- ghost drawing -----------------------------------------------------------------------------------------------

  function TP.Alpha(layer, inst, a)
    TP.M(TP.C.MODEL_ALPHA, layer, inst, 0, a)
    TP.M(TP.C.TEXT_ALPHA, layer, inst, TP.TEXT_NODE, a)
    for _, p in ipairs(TP.PRIMS) do
      TP.M(TP.C.PRIM_ALPHA, layer, inst, p, a)
    end
  end

  -- the formation of the squad on screen
  function TP.FormationId()
    for _, f in ipairs({"GetTeamDockFormationId", "GetApplyFormationId"}) do
      local fn = rawget(_ENV, f)
      if type(fn) == "function" then
        local ok, id = pcall(fn)
        if ok and type(id) == "number" and id ~= 0 then
          return id
        end
      end
    end
    return 0
  end

  -- the ghost of `param` as the card of slot `slot`, drawn on a layer instance; false when not drawn
  function TP.DrawCard(layer, inst, slot, param, rarity, alpha)
    local leader = slot == TP.LEADER_SLOT
    local main = false
    if not leader and type(IsMainMember) == "function" then
      local ok, m = pcall(IsMainMember, slot)
      main = ok and m == true
    end
    local big = leader
    if not leader and type(IsCharaCardBigtype) == "function" then
      local ok, b = pcall(IsCharaCardBigtype, slot, TP.CARD)
      big = ok and b == true
    end
    local pos = 0
    if main then
      local ok, got, p = pcall(funcLuaCommand, TP.C.FORMATION_INFO, 6, TP.FormationId(), slot)
      pos = (ok and got and type(p) == "number") and p or 0
    elseif not leader and type(GetSoccerCharaCalcParamBestPositionTypeByCharaParamID) == "function"
        and type(ConvertPosTypeToScPosType) == "function" then
      local ok, p = pcall(GetSoccerCharaCalcParamBestPositionTypeByCharaParamID, param, 0)
      if ok then
        local ok2, sp = pcall(ConvertPosTypeToScPosType, p)
        pos = ok2 and sp or 0
      end
    end
    local face = 0
    if type(GetCharaFaceType) == "function" then
      local ok, f = pcall(GetCharaFaceType)
      face = (ok and type(f) == "number") and f or 0
    end
    local manager = false
    if not leader and type(IsManager) == "function" then
      local ok, m = pcall(IsManager, slot)
      manager = ok and m == true
    end
    local drawn = TP.M(TP.C.CARD_BY_PARAM, layer, inst, param, big, leader, pos, face, 1, false, false, rarity, 0,
      false, main, 0, false, false, manager)
    if drawn == false then
      TP.Log("ghost", slot, param, "not drawn")
      return false
    end
    TP.M(TP.C.LAYER_VISIBLE, layer, inst, true)
    -- a ghost's marker: the padlock only. CARD_BY_PARAM leaves these meshes as they are and the retail card draws hide
    -- the padlocks and set the booking card, so the instance's state is set on every draw.
    TP.M(TP.C.MESH_VISIBLE, layer, TP.MESH_LOCK_BIG, big, inst)
    TP.M(TP.C.MESH_VISIBLE, layer, TP.MESH_LOCK_SMALL, not big, inst)
    TP.M(TP.C.MESH_VISIBLE, layer, TP.MESH_BOOKING_BIG, false, inst)
    TP.M(TP.C.MESH_VISIBLE, layer, TP.MESH_BOOKING_SMALL, false, inst)
    TP.Alpha(layer, inst, alpha)
    return true
  end

  -- draw the ghost of `param` on slot `slot` (19 = the coach card)
  function TP.Draw(slot, param, rarity, alpha)
    local leader = slot == TP.LEADER_SLOT
    if not TP.DrawCard(leader and TP.LEADER or TP.CARD, leader and 0 or slot, slot, param, rarity, alpha) then
      return false
    end
    TP.M(TP.C.LAYER_VISIBLE, leader and TP.BLANK_LEADER or TP.BLANK, leader and 0 or slot, false)
    TP.ghost[slot] = param
    return true
  end

  -- a ghost instance that now shows a real card (or nothing) gets its normal look back
  function TP.Unghost(slot)
    if TP.ghost[slot] == nil then
      return
    end
    TP.ghost[slot] = nil
    local leader = slot == TP.LEADER_SLOT
    TP.Alpha(leader and TP.LEADER or TP.CARD, leader and 0 or slot, 1)
  end

  -- ghosts of the squad on screen (`only` = one slot); the ghosts of slots no longer planned are taken off
  function TP.Ghosts(set, ty, only)
    if type(set) ~= "number" then
      return
    end
    local on, alpha, rarity = TP.Info()
    if not on then
      return
    end
    local ghosts = TP.GhostSlots(set, ty or 0)
    local held = TP.hold
    if held ~= nil and held.set == set and held.ty == (ty or 0) then
      ghosts[held.slot] = nil      -- the card in the hand: its slot shows the source frame (TP.MarkHeldSlot)
    end
    for slot in pairs(TP.ghost) do
      if (only == nil or only == slot) and ghosts[slot] == nil then
        TP.Unghost(slot)
        if TP.Occupant(set, ty or 0, slot) == 0 then
          local leader = slot == TP.LEADER_SLOT
          TP.M(TP.C.LAYER_VISIBLE, leader and TP.LEADER or TP.CARD, leader and 0 or slot, false)
          if type(UpdateMemberCharaBlankSlot) == "function" then
            pcall(UpdateMemberCharaBlankSlot, leader and 0 or slot, true, leader or nil)
          end
        end
      end
    end
    for slot, param in pairs(ghosts) do
      if only == nil or only == slot then
        TP.Draw(slot, param, rarity, alpha)
      end
    end
  end

  -- the slot a held ghost left: the retail frame of a held card's origin (StartMemberChangeMode)
  function TP.MarkHeldSlot(slot)
    local big = true
    if type(IsCharaCardBigtype) == "function" then
      local ok, b = pcall(IsCharaCardBigtype, slot)
      big = ok and b == true
    end
    TP.M(TP.C.LAYER_VISIBLE, TP.BLANK, slot, true)
    TP.M(TP.C.MESH_VISIBLE, TP.BLANK, TP.MESH_BLANK_BIG, false, slot)
    TP.M(TP.C.MESH_VISIBLE, TP.BLANK, TP.MESH_BLANK_SMALL, false, slot)
    TP.M(TP.C.MESH_VISIBLE, TP.BLANK, TP.MESH_SOURCE_BIG, big, slot)
    TP.M(TP.C.MESH_VISIBLE, TP.BLANK, TP.MESH_SOURCE_SMALL, not big, slot)
  end

  -- wrap global `name` of the stem: make(orig) returns the wrapper (VRFW_Host around handler, else the global, once)
  TP.wrapped = TP.wrapped or {}
  function TP.Wrap(stem, name, make)
    local H = VRFW_Host or EVT_Host
    if type(H) == "table" and type(H.on) == "function" then
      H.on(stem, name, {id = "BetterQoL.team_planner." .. name, phase = "around", fn = function(nxt, ...)
        return make(nxt)(...)
      end})
      return true
    end
    local cur = rawget(_ENV, name)
    if type(cur) ~= "function" or TP.wrapped[stem .. name] then
      return false
    end
    TP.wrapped[stem .. name] = true
    rawset(_ENV, name, make(cur))
    return true
  end

  -- the card refreshes of the formation INCLUDE on a stem: focus changes redraw the card the cursor left with its handle
  -- (0 on a ghost's slot: card hidden, blank shown), so the ghost is drawn again there. squad() -> set, type
  function TP.WrapCardRefresh(stem, squad)
    TP.Wrap(stem, "UpdateMemberCharaIconInfoByChrStHdl", function(orig)
      return function(...)
        local r = table.pack(orig(...))
        local a = table.pack(...)
        local slot = a[2] or 0
        local layer = a[7] or TP.CARD
        local inst = a[8] or slot
        local set, ty = squad()
        if layer == TP.CARD and inst == slot and type(set) == "number" then
          if r[1] then
            TP.Unghost(slot)
          elseif (a[1] or 0) == 0 then
            pcall(TP.Ghosts, set, ty, slot)
          end
        end
        return table.unpack(r, 1, r.n)
      end
    end)

    TP.Wrap(stem, "UpdateLeaderChara_CommonPostProcess", function(orig)
      return function(a1, a2, a3, a4, ...)
        local r = table.pack(orig(a1, a2, a3, a4, ...))
        local set, ty = squad()
        if a1 == TP.LEADER and type(set) == "number" then
          if (a4 or 0) == 0 then
            pcall(TP.Ghosts, set, ty, TP.LEADER_SLOT)
          else
            TP.Unghost(TP.LEADER_SLOT)
          end
        end
        return table.unpack(r, 1, r.n)
      end
    end)

    TP.Wrap(stem, "UpdateMemberCharaBlankSlot", function(orig)
      return function(a1, a2, a3, ...)
        local r = table.pack(orig(a1, a2, a3, ...))
        local slot = a3 and TP.LEADER_SLOT or (a1 or 0)
        if TP.ghost[slot] ~= nil then
          TP.M(TP.C.LAYER_VISIBLE, a3 and TP.BLANK_LEADER or TP.BLANK, a3 and 0 or slot, false)
        end
        local held = TP.hold
        if held ~= nil and not a3 and a2 == true and held.slot == slot and squad() == held.set then
          TP.MarkHeldSlot(slot)
        end
        return table.unpack(r, 1, r.n)
      end
    end)
  end

  -- the host's retail locals of the stem (nil without EVT_DEBUG)
  function TP.Locals(stem)
    local H = VRFW_Host or EVT_Host
    local h = type(H) == "table" and type(H.hosts) == "table" and H.hosts[stem] or nil
    return h ~= nil and h.L or nil
  end

  function TP.Local(stem, k)
    local L = TP.Locals(stem)
    if L == nil then
      return nil
    end
    local ok, v = pcall(function()
      return L[k]
    end)
    return ok and v or nil
  end

  function TP.SetLocal(stem, k, v)
    local L = TP.Locals(stem)
    if L == nil then
      return false
    end
    return (pcall(function()
      L[k] = v
    end))
  end

  -- the retail locals of the squad on screen: each of the three screens has its own, and its own L1 / R1 changes it
  TP.VIEWED = {
    soccer_team_dock_menu = {set = "n5", ty = "n10"},
    team_dock_formation_menu = {set = "n", ty = "n10"},
    chara_bank_menu = {set = "n5"},
  }

  -- the squad the player is looking at on `stem`: set (nil when unreadable), team type
  function TP.ViewedSquad(stem)
    local v = TP.VIEWED[stem]
    if v == nil then
      return nil, 0
    end
    return TP.Local(stem, v.set), (v.ty ~= nil and TP.Local(stem, v.ty)) or 0
  end

  local STEM = "chara_bank_menu"
  local B = TP.B or {}
  TP.B = B
  B.LIST = 449417347             -- team14_01_chara_bank_list
  B.CHECK_MARK = 30530992        -- team00_01_p4_check_mark
  B.HIDDEN_MESHES = {814224422 --[[_icon_lock01]], 2843821468 --[[_icon_lock02]], 2635558741 --[[_icon_card01]],
                     69091055 --[[_icon_card02]]}
  B.MESH_VISIBLE = 3405944500    -- CMND_SET_MESH_VISIBLE (layer, mesh, on, instance)
  B.BACK = 1842266423            -- OnFunction: back (the bank closes)

  function B.Reset()
    B.on, B.set, B.ty, B.slot, B.focus, B.ghosts = false, nil, 0, nil, nil, {}
  end

  -- the param of list row `i` when it is a character not owned (0 = an owned card or none)
  function B.Entry(i)
    local p = TP.Cmd(TP.C.BANK_ENTRY, i)
    return type(p) == "number" and p or 0
  end

  -- a character not owned: his card from the param, small as the bank's cards, at the ghost alpha
  function B.Draw(layer, inst, param)
    local on, alpha, rarity = TP.Info()
    if not on then
      return
    end
    local pos = 0
    if type(GetSoccerCharaCalcParamBestPositionTypeByCharaParamID) == "function"
        and type(ConvertPosTypeToScPosType) == "function" then
      local ok, p = pcall(GetSoccerCharaCalcParamBestPositionTypeByCharaParamID, param, 0)
      if ok then
        local ok2, sp = pcall(ConvertPosTypeToScPosType, p)
        pos = (ok2 and type(sp) == "number") and sp or 0
      end
    end
    local face = 0
    if type(GetCharaFaceType) == "function" then
      local ok, f = pcall(GetCharaFaceType)
      face = (ok and type(f) == "number") and f or 0
    end
    local drawn = TP.M(TP.C.CARD_BY_PARAM, layer, inst, param, false, false, pos, face, 1, false, false, rarity, 0,
      false, true, 0, false, false, false)
    TP.M(TP.C.LAYER_VISIBLE, layer, inst, drawn ~= false)
    TP.M(TP.C.LAYER_VISIBLE, B.CHECK_MARK, inst, false)
    for _, mesh in ipairs(B.HIDDEN_MESHES) do
      TP.M(B.MESH_VISIBLE, layer, mesh, false, inst)
    end
    TP.Alpha(layer, inst, alpha)
    B.ghosts[inst] = true
  end

  -- A on the list's focused card: he goes to the planned slot of the squad on screen (the bank has its own L1 / R1), then
  -- the bank closes
  function B.Pick()
    local h = type(GetSelectedCharaStHdlInList) == "function" and GetSelectedCharaStHdlInList() or 0
    local viewed = TP.ViewedSquad(STEM)
    local set, ty, slot = type(viewed) == "number" and viewed or B.set, B.ty, B.slot
    if TP.Occupant(set, ty, slot) ~= 0 then
      TP.Log("plan bank: squad", set, ty, "slot", slot, "is no longer empty")
      TP.Snd(TP.SY_ERROR)
      return
    end
    if h ~= 0 then
      local used = false
      if type(IsCharaInTeam) == "function" then
        local okU, u = pcall(IsCharaInTeam, h, set)
        used = okU and u == true
      end
      if used or not TP.Place(set, ty, slot, h) then
        TP.Snd(TP.SY_ERROR)
        return
      end
      TP.SetPlan(set, ty, slot, 0)
      TP.Log("plan bank: squad", set, ty, "slot", slot, "owned card", h, "placed")
    else
      local param = B.focus ~= nil and B.Entry(B.focus) or 0
      if param == 0 or not TP.SetPlan(set, ty, slot, param) then
        TP.Snd(TP.SY_ERROR)
        return
      end
      TP.Log("plan bank: squad", set, ty, "slot", slot, "planned", param)
    end
    TP.Snd(TP.SY_OK)
    B.Close()
  end

  -- the bank's own «back» (the list keeps its cards until the bank's FinalizeMenu switches the plan off)
  function B.Close()
    if type(OnFunction) == "function" then
      OnFunction(B.BACK)
    end
  end

  function B.Off()
    if B.on then
      B.on = false
      TP.Cmd(TP.C.BANK_PLAN, false)
    end
  end

  B.Reset()

  TP.Wrap(STEM, "OnInit", function(orig)
    return function(...)
      B.Reset()
      if VRFW_Param.Has(TP.KEY_PLAN) then
        local set, ty, slot = TP.PlanDecode(VRFW_Param.Get(TP.KEY_PLAN))
        VRFW_Param.Clear(TP.KEY_PLAN)
        if set ~= nil and TP.Info() then
          local n = TP.Cmd(TP.C.BANK_PLAN, true)
          if type(n) == "number" then
            B.on, B.set, B.ty, B.slot = true, set, ty, slot
            TP.Log("plan bank: squad", set, ty, "slot", slot, "characters not owned", n)
          end
        end
      end
      return orig(...)
    end
  end)

  local H = VRFW_Host or EVT_Host
  if type(H) == "table" and type(H.on) == "function" then
    H.on(STEM, "FinalizeMenu", {id = "BetterQoL.team_planner.bank_close", phase = "before", create = true, fn = function()
      B.Off()
    end})
  end

  TP.Wrap(STEM, "UpdateItem", function(orig)
    return function(a1, a2, a3, a4, a5, a6, ...)
      if not B.on then
        return orig(a1, a2, a3, a4, a5, a6, ...)
      end
      if a5 then
        B.focus = a3
      end
      local param = (a4 == 0 and type(a3) == "number") and B.Entry(a3) or 0
      if param == 0 then
        local r = table.pack(orig(a1, a2, a3, a4, a5, a6, ...))
        if a6 and B.ghosts[a2] then
          B.ghosts[a2] = nil
          TP.Alpha(a1, a2, 1)
        end
        return table.unpack(r, 1, r.n)
      end
      -- the retail part without the card (its blank card for a row without a handle), then the param card
      local r = table.pack(orig(a1, a2, a3, a4, a5, false, ...))
      if a6 then
        B.Draw(a1, a2, param)
      end
      return table.unpack(r, 1, r.n)
    end
  end)

  TP.Wrap(STEM, "OnEnter", function(orig)
    return function(a1, a2, ...)
      local mode = TP.Local(STEM, "n18")
      if B.on and a1 == B.LIST and (mode == nil or mode == 0) then
        B.Pick()
        return
      end
      return orig(a1, a2, ...)
    end
  end)
end
